import './styles.css';
import { useState, useMemo } from 'react';

// Simulated attention patterns for demonstration
function generateAttention(words: string[]): number[][] {
  const n = words.length;
  const attention: number[][] = [];

  for (let i = 0; i < n; i++) {
    const row: number[] = [];
    for (let j = 0; j < n; j++) {
      let score = 0.1; // base attention

      // Self-attention (words attend to themselves)
      if (i === j) score += 0.3;

      // Adjacent words get some attention
      if (Math.abs(i - j) === 1) score += 0.15;

      // Simulate subject-verb attention
      const wordI = words[i].toLowerCase();
      const wordJ = words[j].toLowerCase();

      // Articles attend to following nouns
      if (['the', 'a', 'an'].includes(wordJ) && j < i && i - j <= 2) {
        score += 0.25;
      }

      // Verbs attend to subjects
      const verbs = ['is', 'are', 'was', 'were', 'sat', 'ran', 'jumped', 'ate', 'loves', 'runs', 'plays'];
      const nouns = ['cat', 'dog', 'man', 'woman', 'bank', 'river', 'mat', 'boy', 'girl', 'fox'];
      if (verbs.includes(wordI) && nouns.includes(wordJ)) {
        score += 0.35;
      }

      // Pronouns attend to nouns
      const pronouns = ['it', 'he', 'she', 'they', 'him', 'her'];
      if (pronouns.includes(wordI) && nouns.includes(wordJ) && j < i) {
        score += 0.4;
      }

      // Context words for disambiguation
      if (wordI === 'bank' && wordJ === 'river') score += 0.5;
      if (wordI === 'bank' && wordJ === 'money') score += 0.5;

      // Adjectives attend to nouns
      const adjectives = ['quick', 'brown', 'lazy', 'beautiful', 'small', 'big'];
      if (adjectives.includes(wordJ) && nouns.includes(wordI) && j < i && i - j <= 2) {
        score += 0.3;
      }

      row.push(Math.min(1, score));
    }

    // Normalize row to sum to 1 (softmax-like)
    const sum = row.reduce((a, b) => a + b, 0);
    attention.push(row.map(v => v / sum));
  }

  return attention;
}

function AttentionMatrix({ words, attention, selectedWord }: { 
  words: string[]; 
  attention: number[][];
  selectedWord: number | null;
}) {
  return (
    <div className="attention-matrix">
      <div className="matrix-corner"></div>
      <div className="matrix-header">
        {words.map((word, i) => (
          <div key={i} className={`header-cell ${selectedWord === i ? 'highlighted' : ''}`}>
            {word}
          </div>
        ))}
      </div>

      {attention.map((row, i) => (
        <div key={i} className="matrix-row">
          <div className={`row-label ${selectedWord === i ? 'highlighted' : ''}`}>
            {words[i]}
          </div>
          {row.map((val, j) => (
            <div 
              key={j} 
              className={`matrix-cell ${selectedWord === i ? 'row-active' : ''} ${selectedWord === j ? 'col-active' : ''}`}
              style={{ 
                backgroundColor: `rgba(124, 58, 237, ${val})`,
                color: val > 0.3 ? 'white' : '#374151'
              }}
            >
              {(val * 100).toFixed(0)}%
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

function AttentionArrows({ words, attention, selectedWord }: {
  words: string[];
  attention: number[][];
  selectedWord: number | null;
}) {
  if (selectedWord === null) return null;

  const row = attention[selectedWord];
  const sortedIndices = row
    .map((val, idx) => ({ val, idx }))
    .sort((a, b) => b.val - a.val)
    .slice(0, 3);

  return (
    <div className="attention-sentence">
      <div className="sentence-label">
        "<strong>{words[selectedWord]}</strong>" attends most to:
      </div>
      <div className="word-row">
        {words.map((word, i) => {
          const attentionVal = row[i];
          const isTop = sortedIndices.some(s => s.idx === i);
          const rank = sortedIndices.findIndex(s => s.idx === i);

          return (
            <div 
              key={i} 
              className={`sentence-word ${i === selectedWord ? 'selected' : ''} ${isTop ? 'top-attention' : ''}`}
              style={{
                opacity: 0.3 + attentionVal * 0.7,
                transform: isTop ? `scale(${1 + attentionVal * 0.3})` : 'scale(1)',
              }}
            >
              {word}
              {isTop && rank !== -1 && (
                <span className="attention-badge">
                  {Math.round(attentionVal * 100)}%
                </span>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

export default function App() {
  const [input, setInput] = useState('The quick brown fox jumped over the lazy dog');
  const [selectedWord, setSelectedWord] = useState<number | null>(null);

  const words = useMemo(() => input.split(/\s+/).filter(w => w.length > 0), [input]);
  const attention = useMemo(() => generateAttention(words), [words]);

  return (
    <div className="app">
      <div className="header">
        <h1>Attention Visualizer</h1>
        <p className="subtitle">
          See how words "pay attention" to each other in a Transformer.
        </p>
      </div>

      <div className="input-section">
        <label>Enter a sentence</label>
        <input
          type="text"
          value={input}
          onChange={(e) => {
            setInput(e.target.value);
            setSelectedWord(null);
          }}
          placeholder="Type a sentence..."
          className="text-input"
        />
        <div className="suggestions">
          Try: "The bank by the river was peaceful" or "She gave him the book"
        </div>
      </div>

      <div className="word-selector">
        <label>Click a word to see what it attends to:</label>
        <div className="word-buttons">
          {words.map((word, i) => (
            <button
              key={i}
              className={`word-btn ${selectedWord === i ? 'selected' : ''}`}
              onClick={() => setSelectedWord(selectedWord === i ? null : i)}
            >
              {word}
            </button>
          ))}
        </div>
      </div>

      {selectedWord !== null && (
        <AttentionArrows words={words} attention={attention} selectedWord={selectedWord} />
      )}

      <div className="matrix-section">
        <h3>Attention Matrix</h3>
        <p className="matrix-hint">
          Each row shows how much that word attends to every other word.
          Darker = stronger attention.
        </p>
        <div className="matrix-wrapper">
          <AttentionMatrix 
            words={words} 
            attention={attention} 
            selectedWord={selectedWord}
          />
        </div>
        <div className="matrix-labels">
          <span>← Each row sums to 100%</span>
          <span>Read: Row word pays X% attention to column word</span>
        </div>
      </div>

      <div className="insight-box">
        <h3>What Attention Does</h3>
        <p>
          In Transformers, each word can "look at" every other word simultaneously—not just neighbors.
        </p>
        <p>
          <strong>Disambiguation:</strong> "Bank" near "river" attends to "river" to understand it means riverbank.
        </p>
        <p>
          <strong>Coreference:</strong> Pronouns like "it" or "she" attend strongly to the nouns they refer to.
        </p>
        <p>
          <strong>Structure:</strong> Verbs attend to their subjects. Adjectives attend to their nouns.
        </p>
      </div>
    </div>
  );
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, sans-serif;
  background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%);
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.app {
  max-width: 900px;
  margin: 0 auto;
}

.header {
  text-align: center;
  margin-bottom: 1.5rem;
}

h1 {
  color: white;
  font-size: 1.75rem;
  margin-bottom: 0.5rem;
}

.subtitle {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.95rem;
}

.input-section {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.input-section label {
  display: block;
  font-size: 0.8rem;
  color: #6b7280;
  margin-bottom: 0.5rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.text-input {
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1rem;
  border: 2px solid #e5e7eb;
  border-radius: 0.5rem;
  outline: none;
  transition: border-color 0.2s;
}

.text-input:focus {
  border-color: #7c3aed;
}

.suggestions {
  font-size: 0.8rem;
  color: #9ca3af;
  margin-top: 0.5rem;
}

.word-selector {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.word-selector label {
  display: block;
  font-size: 0.85rem;
  color: #374151;
  margin-bottom: 0.75rem;
}

.word-buttons {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.word-btn {
  padding: 0.5rem 1rem;
  background: #f3f4f6;
  border: 2px solid transparent;
  border-radius: 0.5rem;
  font-size: 0.95rem;
  cursor: pointer;
  transition: all 0.2s;
}

.word-btn:hover {
  border-color: #7c3aed;
}

.word-btn.selected {
  background: #7c3aed;
  color: white;
}

.attention-sentence {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.sentence-label {
  font-size: 0.9rem;
  color: #374151;
  margin-bottom: 1rem;
}

.word-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
}

.sentence-word {
  position: relative;
  padding: 0.5rem 0.75rem;
  background: #f3f4f6;
  border-radius: 0.5rem;
  font-size: 1rem;
  transition: all 0.3s;
}

.sentence-word.selected {
  background: #7c3aed;
  color: white;
}

.sentence-word.top-attention {
  background: #ddd6fe;
  font-weight: 600;
}

.attention-badge {
  position: absolute;
  top: -8px;
  right: -8px;
  background: #7c3aed;
  color: white;
  font-size: 0.65rem;
  padding: 0.15rem 0.35rem;
  border-radius: 0.25rem;
  font-weight: 700;
}

.matrix-section {
  background: white;
  border-radius: 1rem;
  padding: 1.25rem;
  margin-bottom: 1rem;
}

.matrix-section h3 {
  font-size: 1rem;
  color: #1f2937;
  margin-bottom: 0.5rem;
}

.matrix-hint {
  font-size: 0.85rem;
  color: #6b7280;
  margin-bottom: 1rem;
}

.matrix-wrapper {
  overflow-x: auto;
  padding: 0.5rem 0;
}

.attention-matrix {
  display: inline-block;
  font-size: 0.75rem;
}

.matrix-corner {
  display: inline-block;
  width: 70px;
  height: 30px;
}

.matrix-header {
  display: flex;
  margin-left: 70px;
}

.header-cell {
  width: 55px;
  text-align: center;
  font-weight: 600;
  color: #374151;
  padding: 0.25rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-cell.highlighted {
  color: #7c3aed;
  background: #f3e8ff;
}

.matrix-row {
  display: flex;
  align-items: center;
}

.row-label {
  width: 70px;
  text-align: right;
  padding-right: 0.5rem;
  font-weight: 600;
  color: #374151;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.row-label.highlighted {
  color: #7c3aed;
  background: #f3e8ff;
}

.matrix-cell {
  width: 55px;
  height: 35px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #e5e7eb;
  font-size: 0.7rem;
  transition: all 0.2s;
}

.matrix-cell.row-active,
.matrix-cell.col-active {
  border-color: #7c3aed;
}

.matrix-labels {
  display: flex;
  justify-content: space-between;
  font-size: 0.75rem;
  color: #9ca3af;
  margin-top: 0.75rem;
}

.insight-box {
  background: rgba(255, 255, 255, 0.95);
  border-radius: 1rem;
  padding: 1.25rem;
}

.insight-box h3 {
  color: #1f2937;
  font-size: 1rem;
  margin-bottom: 0.75rem;
}

.insight-box p {
  color: #4b5563;
  font-size: 0.9rem;
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.insight-box p:last-child {
  margin-bottom: 0;
}

@media (max-width: 600px) {
  .matrix-section {
    overflow: hidden;
  }

  .header-cell,
  .matrix-cell {
    width: 45px;
    font-size: 0.65rem;
  }

  .row-label {
    width: 55px;
    font-size: 0.7rem;
  }
}
